'use strict';

exports.waits = function (options) {
  return [this.waitFor(0, options), this.waitFor(1, options)];
};

exports.waitFor = function (attempt, options) {
  return options.base * (attempt + 1);
};

exports.run = function () {
  var detached = exports.waits;
  var first;
  try {
    first = detached({ base: 1 }).join(',');
  } catch (e) {
    first = e instanceof TypeError ? 'TypeError' : 'other';
  }
  return first + '|' + exports.waits({ base: 4 }).join(',');
};
